#include <bits/stdc++.h>
using namespace std;
const int N=16; const int FULL=(1<<16)-1; using V=vector<array<double,N>>;
vector<array<int,6>> mk(bool sh){vector<array<int,6>> adj(16);for(int v=0;v<16;v++){int x=v/4,y=v%4;vector<int> nb;for(int u=0;u<16;u++){if(u==v)continue;int a=(u/4-x+4)%4,b=(u%4-y+4)%4;bool ok=sh ? ((a==1&&b==0)||(a==3&&b==0)||(a==0&&b==1)||(a==0&&b==3)||(a==1&&b==1)||(a==3&&b==3)):(u/4==x || u%4==y);if(ok)nb.push_back(u);}if(nb.size()!=6)abort();copy(nb.begin(),nb.end(),adj[v].begin());}return adj;}
double solve(bool sh){auto adj=mk(sh);V E(FULL+1);for(int s=FULL-1;s>=1;s--){int nodes[16],k=0;for(int i=0;i<16;i++)if(s>>i&1)nodes[k++]=i;double a[16][17]={};for(int i=0;i<k;i++){int v=nodes[i];a[i][i]=6;a[i][k]=6;for(int w:adj[v]){if(s>>w&1){for(int j=0;j<k;j++)if(nodes[j]==w){a[i][j]-=1;break;}}else{a[i][k]+=E[s | (1<<w)][w];}}}for(int i=0;i<k;i++){int ip=i;while(ip<k&&abs(a[ip][i])<1.e-12)ip++;if(ip==k)abort();if(ip!=i)for(int j=i;j<=k;j++)swap(a[i][j],a[ip][j]);double d=a[i][i];for(int j=i+1;j<k;j++){double m=a[j][i]/d;for(int l=i+1;l<=k;l++)a[j][l]-=m*a[i][l];} }for(int i=k-1;i>=0;i--){double v=a[i][k];for(int j=i+1;j<k;j++)v-=a[i][j]*E[s][nodes[j]];E[s][nodes[i]]=v/a[i][i];}}return E[1][0];}
int main(){auto start=chrono::steady_clock::now();double a=solve(false);double b=solve(true);cout<<setprecision(17)<<"rook "<<a<<" shrikhande "<<b<<" difference "<<(b-a)<<"\n";cerr<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<" seconds\n";}
